{
  "new_proposition": {
    "id": "594034",
    "chronological_turn": 27,
    "speaker": "Bonnie Greer",
    "text": "having to deal with talking about least worse as if we’re talking about choosing a television host instead of a leader of the free world is a terrible, horrible mess"
  },
  "complete_earlier_comparison_block": [
    {
      "id": "593998",
      "chronological_turn": 17,
      "speaker": "Bonnie Greer",
      "text": "the last two years Anthony Scaramucci has been incredible in terms of coming clean on TV in front of people, he published a book, he is behind the incredible Lincoln Project of Conservatives and Republicans who are actually trying to save conservatism and make it decent again"
    },
    {
      "id": "594002",
      "chronological_turn": 18,
      "speaker": "Bonnie Greer",
      "text": "the other thing that Anthony Scaramucci did, because of his charisma, his intelligence, is that he normalised Donald Trump, and that’s the problem"
    },
    {
      "id": "594006",
      "chronological_turn": 19,
      "speaker": "Bonnie Greer",
      "text": "Bonnie Greer is not saying that Anthony Scaramucci is the only one that normalised Donald Trump"
    },
    {
      "id": "594065",
      "chronological_turn": 20,
      "speaker": "Bonnie Greer",
      "text": "Bonnie Greer is talking about all of the very intelligent people at the beginning who flocked around Donald Trump because of their political beliefs"
    },
    {
      "id": "594010",
      "chronological_turn": 21,
      "speaker": "Bonnie Greer",
      "text": "Donald Trump was out of order for 30 years"
    },
    {
      "id": "594014",
      "chronological_turn": 22,
      "speaker": "Bonnie Greer",
      "text": "very intelligent people who flocked around Donald Trump because of their political beliefs just didn’t happen"
    },
    {
      "id": "594018",
      "chronological_turn": 23,
      "speaker": "Bonnie Greer",
      "text": "we’re now having to deal with talking about least worse as if we’re talking about choosing a television host instead of a leader of the free world"
    },
    {
      "id": "594022",
      "chronological_turn": 24,
      "speaker": "Bonnie Greer",
      "text": "having to deal with talking about least worse as if we’re talking about choosing a television host instead of a leader of the free world is horrible"
    }
  ]
}

